// Monta o e-mail HTML do Financeiro (padrão visual ASTER)
// Desde 19/11/2026 o Financeiro tem só a etapa de cadastro: o Termo de Aceite (formulário) já chega preenchido no fluxo 0.
const f = $('Buscar Item no Lists').item.json.fields || {};
// Link de retomada: troca o host (localhost) pelo endereço acessível na rede
// e coloca o sufixo da etapa ANTES da query (?signature=<<PREENCHER>>
const urlN8n = String($('Configuração').item.json.urlN8n || '').trim().replace(/\/$/, '');
let resume = $execution.resumeUrl;
if (urlN8n && !urlN8n.includes('IP-DO-SERVIDOR')) resume = resume.replace(/^https?:\/\/[^/]+/, urlN8n);
const [resumePath, resumeQuery] = resume.split('?');
const linkEtapa = key => `${resumePath}/${key}?${resumeQuery ? resumeQuery + '&' : ''}acao=confirmar`;
const REENVIO_DIAS = 3;

const VERMELHO = '#c1291b';
const ESCURO = '#333333';
const CINZA = '#6b7280';
const BORDA = '#e5e7eb';
const VERDE = '#2e7d32';
const FONTE = "'Segoe UI', Arial, Helvetica, sans-serif";

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const data = d => {
  if (!d) return 'Não informada';
  const dt = DateTime.fromISO(String(d), { zone: 'utc' }).setZone('America/Sao_Paulo');
  return dt.isValid ? dt.toFormat('dd/MM/yyyy') : esc(d);
};
const linhas = t => (t ? String(t).split('\n').map(s => s.trim()).filter(Boolean) : []);

const ETAPAS = [
  { key: 'cadastro', titulo: 'Cadastro financeiro',
    acao: 'Realizar os <b>cadastros financeiros</b> do novo cliente nos sistemas internos.',
    botao: 'Confirmar cadastro realizado' }
];

// ---------- blocos ----------
const stepper = atual => `
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tr>
${ETAPAS.map((e, i) => {
  const feito = i < atual, corrente = i === atual;
  const cor = feito ? VERDE : corrente ? VERMELHO : '#d1d5db';
  const txt = feito ? '#ffffff' : corrente ? '#ffffff' : CINZA;
  const simbolo = feito ? '&#10003;' : String(i + 1);
  return `<td width="33%" align="center" valign="top" style="padding:0 4px;">
    <table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center"><tr>
      <td width="30" height="30" align="center" valign="middle" bgcolor="${cor}"
          style="width:30px;height:30px;border-radius:15px;font-family:${FONTE};font-size:14px;font-weight:700;color:${txt};">${simbolo}</td>
    </tr></table>
    <div style="font-family:${FONTE};font-size:12px;line-height:16px;margin-top:6px;color:${corrente ? ESCURO : CINZA};font-weight:${corrente ? 700 : 400};">${e.titulo}</div>
  </td>`;
}).join('')}
</tr></table>`;

const linhaInfo = (rotulo, valor, destaque) => `
<tr>
  <td style="padding:9px 0;border-bottom:1px solid ${BORDA};font-family:${FONTE};font-size:13px;color:${CINZA};width:38%;" valign="top">${rotulo}</td>
  <td style="padding:9px 0;border-bottom:1px solid ${BORDA};font-family:${FONTE};font-size:14px;color:${ESCURO};font-weight:${destaque ? 700 : 600};" valign="top">${valor}</td>
</tr>`;

const titulo = t => `<div style="font-family:${FONTE};font-size:12px;font-weight:700;letter-spacing:1px;color:${VERMELHO};text-transform:uppercase;margin:26px 0 8px;">${t}</div>`;

// Coluna "Cliente" do Lists: um cliente por linha → "Nome, Rua e número, e-mail[, Tel: ...]"
const dadoCliente = (rotulo, valor) => `
  <tr>
    <td style="padding:2px 0;font-family:${FONTE};font-size:12px;color:${CINZA};width:72px;" valign="top">${rotulo}</td>
    <td style="padding:2px 0;font-family:${FONTE};font-size:13px;color:${ESCURO};" valign="top">${valor}</td>
  </tr>`;

// Coluna "Cliente" = só o nome; Telefone, Email, Rua e Numero ficam em colunas próprias (uma linha por cliente).
// Itens antigos: "Nome, Rua e número, e-mail, Tel: ..." na própria coluna Cliente.
const linhasCliente = f => {
  const col = v => String(v || '').split('\n').map(s => s.trim());
  const nomes = col(f.Cliente || f.Bolsao).filter(Boolean);
  if (!(f.Telefone || f.Email || f.Rua || f.Numero)) return nomes;
  return nomes.map((nome, i) => {
    const partes = [nome.replace(/,/g, ' '), [col(f.Rua)[i], col(f.Numero)[i]].filter(Boolean).join(' ').replace(/,/g, ' '), col(f.Email)[i]].filter(Boolean);
    if (col(f.Telefone)[i]) partes.push('Tel: ' + col(f.Telefone)[i]);
    return partes.join(', ');
  });
};
const contratantes = linhasCliente(f).map(l => {
  const partes = l.split(',').map(s => s.trim()).filter(Boolean);
  const nome = (partes.shift() || '').split(' — ')[0];
  const email = (l.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/) || [])[0] || null;
  const tel = (l.match(/Tel\.?:\s*([^,]+)/i) || [])[1] || null;
  const endereco = partes.filter(s => !s.includes('@') && !/^Tel\.?:/i.test(s)).join(', ') || null;
  return `
  <tr><td style="padding:0 0 10px 0;">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"
           style="background:#f9fafb;border:1px solid ${BORDA};border-left:4px solid ${VERMELHO};border-radius:6px;">
      <tr><td style="padding:12px 16px;">
        <div style="font-family:${FONTE};font-size:14px;font-weight:700;color:${ESCURO};margin-bottom:6px;">${esc(nome || 'Não informado')}</div>
        <table role="presentation" cellspacing="0" cellpadding="0" border="0">
          ${dadoCliente('Endereço', esc(endereco || 'Não informado'))}
          ${dadoCliente('E-mail', email ? `<a href="mailto:${esc(email)}" style="color:${VERMELHO};text-decoration:none;">${esc(email)}</a>` : 'Não informado')}
          ${tel ? dadoCliente('Telefone', esc(tel.trim())) : ''}
        </table>
      </td></tr>
    </table>
  </td></tr>`;
}).join('') || `<tr><td style="font-family:${FONTE};font-size:14px;color:${CINZA};">Não informado</td></tr>`;

const servicos = linhas(f.ServicosContratados).map(l => {
  const desc = l.replace(/\s+—\s+R\$.*$/, '');   // nunca exibe valores
  return `<tr><td style="padding:7px 0;border-bottom:1px solid ${BORDA};font-family:${FONTE};font-size:14px;color:${ESCURO};">${esc(desc)}</td></tr>`;
}).join('') || `<tr><td style="font-family:${FONTE};font-size:14px;color:${CINZA};">Não informado</td></tr>`;

const botao = (texto, url) => `
<table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr>
  <td align="center" bgcolor="${VERMELHO}" style="border-radius:6px;">
    <a href="${url}" target="_blank"
       style="display:inline-block;padding:15px 36px;font-family:${FONTE};font-size:15px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:6px;">&#10003;&nbsp;&nbsp;${texto}</a>
  </td>
</tr></table>`;

const montar = (atual) => {
  const e = ETAPAS[atual];
  const url = linkEtapa(e.key);
  return `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"></head>
<body style="margin:0;padding:0;background:#f3f4f6;">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#f3f4f6"><tr><td align="center" style="padding:28px 12px;">
<table role="presentation" width="600" cellspacing="0" cellpadding="0" border="0" style="width:600px;max-width:600px;background:#ffffff;border-radius:8px;overflow:hidden;border:1px solid ${BORDA};">

  <!-- Cabeçalho -->
  <tr><td bgcolor="${VERMELHO}" style="padding:22px 32px;">
    <div style="font-family:${FONTE};font-size:20px;font-weight:800;letter-spacing:3px;color:#ffffff;">GRUPO ASTER</div>
    <div style="font-family:${FONTE};font-size:13px;color:#fde2df;margin-top:2px;">Inclusão de Cliente &nbsp;·&nbsp; Financeiro</div>
  </td></tr>

  <!-- Etapas -->
  ${ETAPAS.length > 1 ? `<tr><td style="padding:24px 32px 8px;">${stepper(atual)}</td></tr>` : ''}

  <!-- Chamada -->
  <tr><td style="padding:18px 32px 0;">
    ${ETAPAS.length > 1 ? `<div style="font-family:${FONTE};font-size:12px;color:${CINZA};">Etapa ${atual + 1} de ${ETAPAS.length}</div>` : ''}
    <div style="font-family:${FONTE};font-size:22px;font-weight:700;color:${ESCURO};margin:4px 0 14px;">${e.titulo}</div>
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tr>
      <td width="4" bgcolor="${VERMELHO}" style="width:4px;"></td>
      <td bgcolor="#fdf2f1" style="padding:14px 16px;font-family:${FONTE};font-size:14px;line-height:21px;color:${ESCURO};">
        <b style="color:${VERMELHO};">Ação necessária:</b><br>${e.acao}
      </td>
    </tr></table>
  </td></tr>

  <!-- Dados -->
  <tr><td style="padding:0 32px;">
    ${titulo('Dados da adesão')}
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">
      ${linhaInfo('Bolsão', esc(f.Title || 'Não informado'), true)}
      ${f.EmpresaAster ? linhaInfo('Empresa ASTER', esc(f.EmpresaAster)) : ''}
      ${f.NumeroProposta ? linhaInfo('Proposta', esc(f.NumeroProposta)) : ''}
      ${linhaInfo('Tipo de movimento', esc(f.TipoMovimento || '—'))}
      ${linhaInfo('Data do aceite', data(f.DataAssinatura))}
    </table>

    ${titulo('Cliente')}
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">${contratantes}</table>

    ${linhas(f.ServicosContratados).length ? `${titulo('Serviços contratados')}
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">${servicos}</table>` : ''}
  </td></tr>

  <!-- Botão -->
  <tr><td align="center" style="padding:32px 32px 12px;">${botao(e.botao, url)}</td></tr>
  <tr><td align="center" style="padding:0 32px 28px;font-family:${FONTE};font-size:12px;color:${CINZA};">
    Clique somente após concluir a etapa.
  </td></tr>

  <!-- Rodapé -->
  <tr><td bgcolor="#f9fafb" style="padding:16px 32px;border-top:1px solid ${BORDA};font-family:${FONTE};font-size:11px;line-height:17px;color:${CINZA};">
    Enquanto esta etapa não for confirmada, este e-mail será reenviado a cada ${REENVIO_DIAS} dias.<br>
    Mensagem automática da Automação de Inclusão de Clientes — Grupo ASTER. Não responda este e-mail.
  </td></tr>

</table>
</td></tr></table>
</body></html>`;
};

// Link interno de retomada (usado pelo workflow que sincroniza alterações feitas direto no Lists)
const [resumeInternoPath, resumeInternoQuery] = String($execution.resumeUrl).split('?');

return [{
  json: {
    cliente: f.Title || 'Cliente',
    resumeInterno: { path: resumeInternoPath, query: resumeInternoQuery || '' },
    html: { cadastro: montar(0) }
  }
}];

// Antes de reenviar o lembrete, confere o item no Lists
const f = $json.fields;
if (!f) return [{ json: { acao: 'encerrar', motivo: 'item não encontrado no Lists' } }];
if (f.StatusAutomacao !== 'Aguardando Financeiro e Cadastros')
  return [{ json: { acao: 'encerrar', motivo: 'inclusão não está mais na fase do Financeiro' } }];
const NIVEL = { 'Aguardando Cadastro': 0, 'Cadastro Realizado': 1, 'Aguardando Formulario': 1,
  'Formulario Enviado': 2, 'Formulario Recebido': 3, 'Concluido': 3 };
// Etapa já marcada no Lists, mas a confirmação não chegou aqui: segue o fluxo sem reenviar
if ((NIVEL[f.FinanceiroStatus] ?? 0) >= 1) return [{ json: { acao: 'seguir' } }];
// Sábado ou domingo: segura o lembrete até segunda 8h
const agora = $now.setZone('America/Sao_Paulo');
if (agora.weekday >= 6) {
  const segunda = agora.plus({ days: 8 - agora.weekday }).set({ hour: 8, minute: 0, second: 0, millisecond: 0 });
  return [{ json: { acao: 'aguardar', ate: segunda.toISO() } }];
}
return [{ json: { acao: 'reenviar' } }];
